            'transition_checks':t,'cycle_transition_checks':lam,'boundary_triangular_checks':4*p}

def bit_at(rec,j,i):
    a=rec['spatial_onset']; lam=rec['lambda']
    if i>=a: i=a+(i-a)%lam
    return (rec['columns'][i]>>j)&1

def pack(rec,j,start,length):
    return int(''.join(str(bit_at(rec,j,i)) for i in range(start+length-1,start-1,-1)),2) if length else 0

def certify(rec):
    q=rec['q']; p=len(q); a=rec['spatial_onset']; lam=rec['lambda']; precision=a+lam+4
    phasepacks=[pack(rec,j,0,precision+2) for j in range(p)]
    modulus=(1<<precision)-1
    rational=[]; zeroruns=[]
    for j in range(p):
        check_time()
        A=pack(rec,j,0,a); C=pack(rec,j,a,lam); D=(1<<lam)-1; N=A*D-(C<<a)
        divisor=math.gcd(N,D); N//=divisor; D//=divisor
        assert ((N-D*phasepacks[j])&((1<<(precision+2))-1))==0
        assert ((T(P(phasepacks[j]>>2)) ^ int(q[j]=='u')) & modulus)==(phasepacks[(j+1)%p]&modulus)
        rational.append({'phase':j,'A_hex':hex(A),'C_hex':hex(C),'numerator_hex':hex(N),'denominator_hex':hex(D)})
        s=a+(a%2); digits=[bit_at(rec,j,s+2*i)+2*bit_at(rec,j,s+2*i+1) for i in range(lam//math.gcd(lam,2))]
        length=len(digits); best=run=0; beststart=None
        for i in range(2*length):
            run=min(length,run+1) if digits[i%length]==0 else 0
            if run>best: best=run; beststart=(i-run+1)%length
        zeroruns.append({'phase':j,'aligned_start_bit':s,'base4_period_digits':length,'cyclic_max_zero_digits':best,
                         'first_max_start_digit':beststart,'all_zero':best==length,'digits_sha256':sha(bytes(digits))})
    rec.update(rational_phases=rational,zero_runs=zeroruns,packed_phase_equation_checks=p*precision,
               phase_equation_precision_bits=precision,certificate_status='complete')
    if q=='t': assert (rational[0]['numerator_hex'],rational[0]['denominator_hex'])==('0x1','0x3')
    if q=='u': assert (rational[0]['numerator_hex'],rational[0]['denominator_hex'])==('0x5','0x3')

CANONICAL=tuple(g for g in TRIPLES if g[2]==2 and g[:2]!=(2,3))
assert len(CANONICAL)==15

def fast_orbit(x,horizon):
    letters=[]; current=x
    for i in range(horizon):
        if i%128==0: check_time()
        r=current&15
        if r not in (7,11): return ''.join(letters),'nonforcing_residue'
        letter='u' if r==7 else 't'; letters.append(letter)
        current=T(P(current>>2)) ^ int(letter=='u')
        # Once this prefix is inadmissible, no later full-prefix occurrence can qualify.
        # Retain the just-created forbidden suffix so earlier occurrences are still tested.
        tail=''.join(letters[-6:])
        if not admissible(tail): return ''.join(letters),'inadmissibility_pruning'
    return ''.join(letters),'observation_horizon'

def find_occurrence(word,k):
    for c in range(max(0,k-2),len(word)):
        for g in CANONICAL:
            E=motif(g); end=c+len(E)
            if word[c:end]==E and admissible(word[:end]+'u'):
                return {'c':c,'gaps':list(g),'w':word[:c],'E':E,'observed_prefix':word[:end],
                        'admissibility_word':word[:end]+'u','appended_final_u_observed':False}
    return None

def truncations(rec):
    q=rec['q']; p=len(q); end=rec['spatial_onset']+rec['lambda']; xs=[0]*p; seen=set()
    stats={'status':'running','maximum_cut_inclusive':end,'positions_completed':0,'phase_candidates':0,
           'unique_x_tested':0,'duplicates_skipped':0,'x_below_4_skipped':0,'forced_symbols':0,'stop_reasons':{},'witness':None}
    rec['truncation_scan']=stats
    try:
        for N in range(1,end+1):
            for j in range(p):
                check_time(); xs[j] |= bit_at(rec,j,N-1)<<(N-1); x=xs[j]
                stats['last_started']={'binary_cut':N,'phase':j}; stats['phase_candidates']+=1
                if x<4: stats['x_below_4_skipped']+=1; continue
                if x in seen: stats['duplicates_skipped']+=1; continue
                seen.add(x); k=(x.bit_length()+1)//2
                word,reason=fast_orbit(x,k+14); found=find_occurrence(word,k)
                stats['unique_x_tested']+=1; stats['forced_symbols']+=len(word)
                stats['stop_reasons'][reason]=stats['stop_reasons'].get(reason,0)+1
                if found:
                    # Full exact replay with scalar-cell crosscheck at every transition.
                    states,steps,fullword,stop=orbit(x,k+14)
                    assert find_occurrence(fullword,k)==found
                    stats['witness']={'x_hex':hex(x),'binary_cut':N,'phase':j,'bit_length':x.bit_length(),'k':k,
                        'horizon':k+14,'full_orbit_hex':[hex(v) for v in states],'steps':steps,
                        'full_observed_word':fullword,'orbit_stop_reason':stop,**found}
                    stats['status']='witness_found'; return
            stats['positions_completed']=N
        stats['status']='complete_no_witness'
    except TimeoutError:
        stats['status']='incomplete_time_cap'

